Future<Map<String, dynamic>> sendSMS({
  required String to,
  required String message,
  String token = 'YOUR_TOKEN',
}) async {
  final url = Uri.parse('https://bulksmsbd.net/api/smsapi');
  final response = await http.post(
    url,
    body: {
      'api_key': token,
      'senderid': '8809617610123', // Your approved ID
      'number': to,
      'message': message,
    },
  );

  try {
    return jsonDecode(response.body);
  } catch (e) {
    return {'error': e.toString(), 'statusCode': response.statusCode};
  }
}

